notes.summary:
{
  "product": "Google Docs Voice Typing",
  "pricing": {
    "cost": "Free",
    "details": "Included at no additional cost with any standard Google account.",
    "date_checked": "2026-11-13"
  },
  "platforms": [
    "Web browsers (Chrome, Edge, Safari) on desktop computers"
  ],
  "main_features": [
    "Real-time speech-to-text transcription within Google Docs and Google Slides speaker notes",
    "Support for approximately 120 languages and accents",
    "Voice commands for formatting and editing (e.g., 'select paragraph', 'bold', 'insert link'), available only when the account and document language are set to English",
    "Spoken punctuation support (e.g., 'period', 'comma', 'new paragraph')"
  ],
  "privacy_statement": "When using voice typing, audio is streamed to Google's cloud servers in real-time for processing. Google's data practices involve capturing audio recordings, transcription text, and usage patterns, which may be retained by Google and accessed for quality review or to train AI models.",
  "reviewer_opinions": [
    "Praised for being free, requiring no installation, and being conveniently built directly into the Google Docs interface.",
    "Often criticized for being limited to Google Docs/Slides and failing to work in other applications like Gmail or Slack.",
    "Reviewers frequently note that the requirement to speak punctuation commands out loud can disrupt the user's train of thought.",
    "Opinions often highlight that it is best suited for short, quick drafts in quiet environments, rather than long-form or professional transcription tasks."
  ],
  "key_statistics": [
    {
      "statistic": "Supports approximately 120 languages and regional variants.",
      "source": "https://support.google.com/docs/answer/4492226"
    },
    {
      "statistic": "Requires a manual start for every session; it does not support background or system-wide dictation.",
      "source": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQHuKBZrwtJ8YfF1IOyh8hJOJ6b2xfqIhzPuRSo1ci7YXRrwN2OjPBHzNJxDg2hGDkXl1lZV6CmSgs-67559rQUC0aiTfHsVjufHnhp7Vg18ccpVuMzVpfmOevKanWQ7_r9lzi3rQZEK4N8FnpjYNPYsfuTABNGqOg=="
    },
    {
      "statistic": "Zero offline capability; the feature requires a constant internet connection to stream audio to cloud servers.",
      "source": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQHl4jCUrj31BwpUHDa9BIccEE58qie761aHdde-6UeuNKFEzG74_EtGT8p7NL6LytmssxltmsgSU9qBeheaF50lhCyzUTVeg7nhRXXJu1ztRXo5r6QLyrRgLZwN_3AK-vqydu_uIUzIn6DKH82UDMFEESAN8MdkZUM5kp6BItBEuu8enZYgiibuVOrzoabkMGXtPV02RfmVXl5UjqrnSIDmlzj7ptY="
    }
  ],
  "caveats": "While Google's help page specifies support for Chrome, Edge, and Safari, some user reports indicate that browser-specific permissions and updates can occasionally cause the feature to fail silently. Additionally, voice commands are strictly limited to English, even when dictating in other supported languages."
}
